import User from '../models/user.model.js';
import { generateToken } from '../utils/jwt.js';
import { errorHandler } from '../utils/error.js';

export const adminSignup = async (req, res, next) => {
  const { username, email, password } = req.body;

  if (!username || !email || !password) {
    return next(errorHandler(400, "All fields are required"));
  }

  try {
    const existingUser = await User.findOne({ email });
    if (existingUser) {
      return next(errorHandler(400, "Email already exists"));
    }

    const newAdmin = await User.create({
      full_name: username,
      email,
      password,
      role: "admin"
    });

    res.status(201).json({ message: "Admin created successfully" });
  } catch (err) {
    next(err);
  }
};

export const adminSignin = async (req, res, next) => {
  try {
    const { email, password } = req.body;

    const admin = await User.findOne({ email, role: 'admin' });
    if (!admin) {
      return next(errorHandler(404, "Admin not found"));
    }

    const isPasswordValid = await admin.comparePassword(password);
    if (!isPasswordValid) {
      return next(errorHandler(401, "Invalid password"));
    }

    const token = generateToken(admin._id, true);

    res.cookie('admin_token', token, {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'strict',
      maxAge: 24 * 60 * 60 * 1000
    });

    res.status(200).json({
      success: true,
      _id: admin._id,
      email: admin.email,
      username: admin.full_name,
      role: admin.role
    });
  } catch (err) {
    next(err);
  }
};

export const adminSignout = (req, res) => {
  res.clearCookie("admin_token");
  res.status(200).json("Admin signout success!");
};

import User from "../models/user.model.js";
import Notification from "../models/notification.model.js";
import { generateToken } from "../utils/jwt.js";
import { errorHandler } from "../utils/error.js";

export const signup = async (req, res, next) => {
  const { username, email, password } = req.body;

  if (!username || !email || !password) {
    return next(errorHandler(400, "All fields are required"));
  }

  try {
    const existingUser = await User.findOne({ email });
    if (existingUser) {
      return next(errorHandler(400, "Email already exists"));
    }

    const newUser = await User.create({
      full_name: username,
      email,
      password,
      role: "user",
    });

    
    const admins = await User.find({ role: "admin" });

    
    const notificationPromises = admins.map((admin) => {
      const notification = new Notification({
        recipient_id: admin._id,
        title: "New User Registered",
        message: `${username} (${email}) has registered a new account.`,
        type: "user",
        reference_id: newUser._id,
        reference_model: "User",
      });
      return notification.save();
    });

    await Promise.all(notificationPromises);

    res.status(201).json({ message: "User created successfully" });
  } catch (err) {
    next(err);
  }
};

export const signin = async (req, res, next) => {
  try {
    const { email, password } = req.body;

    const user = await User.findOne({ email });
    if (!user) {
      return next(errorHandler(404, "User not found"));
    }

    const isPasswordValid = await user.comparePassword(password);
    if (!isPasswordValid) {
      return next(errorHandler(401, "Invalid password"));
    }

    const token = generateToken(user._id, user.role === "admin");

    res.cookie("access_token", token, {
      httpOnly: true,
      secure: process.env.NODE_ENV === "production",
      sameSite: "strict",
      maxAge: 24 * 60 * 60 * 1000,
    });

    res.json({
      _id: user._id,
      email: user.email,
      username: user.full_name,
      role: user.role,
      role: user.role,
      profilePicture: user.profilePicture,
    });
  } catch (err) {
    next(err);
  }
};


export const google = async (req, res, next) => {
  try {
    const { email, name, photo } = req.body;

    let user = await User.findOne({ email });

    if (!user) {
      
      const randomPassword = Math.random().toString(36).slice(-8);
      user = await User.create({
        full_name: name,
        email,
        password: randomPassword,
        profilePicture: photo,
        role: "user",
      });
    }

    const token = generateToken(user._id, user.role === "admin");

    res.cookie("access_token", token, {
      httpOnly: true,
      secure: process.env.NODE_ENV === "production",
      sameSite: "strict",
      maxAge: 24 * 60 * 60 * 1000,
    });

    res.status(200).json({
      _id: user._id,
      email: user.email,
      username: user.full_name,
      photo: user.profilePicture,
      role: user.role,
      profilePicture: user.profilePicture,
      role: user.role,
    });
  } catch (err) {
    next(err);
  }
};

export const signout = (req, res) => {
  try {
    res.clearCookie("access_token");
    res.status(200).json({
      success: true,
      message: "Signout successful!",
    });
  } catch (error) {
    res.status(500).json({
      success: false,
      message: "Signout failed",
    });
  }
};

import Booking from "../models/booking.model.js";
import User from "../models/user.model.js";
import Tour from "../models/tour.model.js";
import Notification from "../models/notification.model.js";

export const createBooking = async (req, res) => {
  console.log("Booking request body:", req.body);
  try {
    const {
      user_id,
      tour_id,
      booking_date,
      total_price,
      number_of_persons,
      status,
    } = req.body;

    if (
      !user_id ||
      !tour_id ||
      !booking_date ||
      !total_price ||
      !number_of_persons
    ) {
      console.log("Missing required fields");
      return res
        .status(400)
        .json({ success: false, message: "Missing required fields" });
    }

    const booking = new Booking({
      user_id,
      tour_id,
      booking_date,
      total_price,
      number_of_persons,
      status: status || "pending",
    });

    await booking.save();

    
    const [tour, user] = await Promise.all([
      Tour.findById(tour_id),
      User.findById(user_id),
    ]);

    
    const admins = await User.find({ role: "admin" });

    
    const notificationPromises = admins.map((admin) => {
      const notification = new Notification({
        recipient_id: admin._id,
        title: "New Booking Created",
        message: `${user.full_name} has booked ${
          tour.title
        } for ${number_of_persons} person(s) on ${new Date(
          booking_date
        ).toLocaleDateString()}.`,
        type: "booking",
        reference_id: booking._id,
        reference_model: "Booking",
      });
      return notification.save();
    });

    await Promise.all(notificationPromises);

    console.log("Booking created:", booking);
    res.status(201).json({ success: true, data: booking });
  } catch (error) {
    console.error("Booking creation error:", error);
    res.status(500).json({ success: false, message: error.message });
  }
};

export const getBookingsByUser = async (req, res) => {
  try {
    const { userId } = req.params;
    const bookings = await Booking.find({ user_id: userId }).populate(
      "tour_id"
    );
    res.json({ success: true, data: bookings });
  } catch (error) {
    console.error("Get bookings by user error:", error);
    res.status(500).json({ success: false, message: error.message });
  }
};

export const getBookingsByTour = async (req, res) => {
  try {
