export const getAllBookings = async (req, res) => {
  try {
    const bookings = await Booking.find()
      .populate("tour_id", "title")
      .populate("user_id", "full_name")
      .sort({ createdAt: -1 });
    res.json({ success: true, data: bookings });
  } catch (error) {
    console.error("Get all bookings error:", error);
    res.status(500).json({ success: false, message: error.message });
  }
};

export const getRevenues = async (req, res) => {
  try {
    const result = await Booking.aggregate([
      { $match: { status: "confirmed" } },
      {
        $group: {
          _id: null,
          totalRevenue: { $sum: "$total_price" },
        },
      },
    ]);

    const totalRevenue = result.length > 0 ? result[0].totalRevenue : 0;

    return res.status(200).json({
      success: true,
      totalRevenue,
    });
  } catch (err) {
    console.error("Error calculating revenue:", err);
    return res.status(500).json({
      success: false,
      message: "Failed to calculate revenue",
    });
  }
};

export const updateBookingStatus = async (req, res) => {
  try {
    const { id } = req.params;
    const { status } = req.body;

    
    const previousBooking = await Booking.findById(id);

    
    const booking = await Booking.findByIdAndUpdate(
      id,
      { status },
      { new: true }
    );

    
    const [tour, user] = await Promise.all([
      Tour.findById(booking.tour_id),
      User.findById(booking.user_id),
    ]);

    
    const admins = await User.find({ role: "admin" });

    
    const adminNotificationPromises = admins.map((admin) => {
      const notification = new Notification({
        recipient_id: admin._id,
        title: "Booking Status Updated",
        message: `Booking for ${tour.title} by ${user.full_name} has been ${status}.`,
        type: "booking_status",
        reference_id: booking._id,
        reference_model: "Booking",
      });
      return notification.save();
    });

    
    const userNotification = new Notification({
      recipient_id: booking.user_id,
      title: "Booking Status Updated",
      message: `Your booking for ${tour.title} has been ${status}.`,
      type: "booking_status",
      reference_id: booking._id,
      reference_model: "Booking",
    });

    await Promise.all([...adminNotificationPromises, userNotification.save()]);

    res.json({ success: true, data: booking });
  } catch (error) {
    console.error("Update booking status error:", error);
    res.status(500).json({ success: false, message: error.message });
  }
};

export const deleteBooking = async (req, res) => {
  try {
    const { id } = req.params;
    await Booking.findByIdAndDelete(id);
    res.json({ success: true, message: "Booking deleted" });
  } catch (error) {
    console.error("Delete booking error:", error);
    res.status(500).json({ success: false, message: error.message });
  }
};

import Tour from "../models/tour.model.js";
import User from "../models/user.model.js";
import Notification from "../models/notification.model.js";
import { errorHandler } from "../utils/error.js";
import { supabaseStorage, uploadToSupabase } from "../utils/supabaseStorage.js";
import { escapeRegex } from "../utils/escapeRegex.js";

export const upload = supabaseStorage;

export const createTour = async (req, res, next) => {
  try {
    console.log("=== createTour START ===");
    console.log("req.body:", JSON.stringify(req.body, null, 2));
    console.log("req.files:", req.files);
    console.log("req.user:", req.user);

    const tourData = {
      ...req.body,
      created_by: req.user.id, 
      price: Number(req.body.price),
      duration_days: Number(req.body.duration_days),
      is_featured:
        req.body.is_featured === "true" || req.body.is_featured === true,
    };

    
    if (req.files) {
      console.log("Files detected:", Object.keys(req.files));

      if (req.files.thumbnail) {
        console.log("Uploading thumbnail to Supabase...");
        const thumbnailResult = await uploadToSupabase(
          req.files.thumbnail[0],
          "tours"
        );
        tourData.thumbnail_url = thumbnailResult.publicUrl;
        console.log("Thumbnail uploaded:", tourData.thumbnail_url);
      }

      if (req.files.gallery) {
        console.log("Uploading gallery images to Supabase...");
        const galleryPromises = req.files.gallery.map((file) =>
          uploadToSupabase(file, "tours")
        );
        const galleryResults = await Promise.all(galleryPromises);
        tourData.gallery_urls = galleryResults.map(
          (result) => result.publicUrl
        );
        console.log("Gallery uploaded:", tourData.gallery_urls);
      }
    } else {
      console.log("No files uploaded");
    }

    console.log("Final tourData:", JSON.stringify(tourData, null, 2));

    
    const newTour = new Tour(tourData);
    const savedTour = await newTour.save();

    
    const admin = await User.findById(req.user.id);

    
    const otherAdmins = await User.find({
      role: "admin",
      _id: { $ne: req.user.id }, 
    });

    
    const notificationPromises = otherAdmins.map((admin) => {
      const notification = new Notification({
        recipient_id: admin._id,
        title: "New Tour Created",
        message: `${admin.full_name} has created a new tour: ${savedTour.title}.`,
        type: "tour_creation",
        reference_id: savedTour._id,
        reference_model: "Tour",
      });
      return notification.save();
    });

    await Promise.all(notificationPromises);

    console.log("Tour created successfully:", savedTour);
    res.status(201).json({ success: true, data: savedTour });
  } catch (error) {
    console.error("createTour error:", error);
    next(error);
  }
};

export const getAllTours = async (req, res, next) => {
  try {
    const tours = await Tour.find().sort({ created_at: -1 });

    res.status(200).json({
      success: true,
      data: tours,
    });
  } catch (error) {
    next(error);
  }
};

export const getTourById = async (req, res, next) => {
  try {
    const tour = await Tour.findById(req.params.id).populate(
      "created_by",
      "full_name"
    );

    if (!tour) return next(errorHandler(404, "Tour not found"));

    res.status(200).json({
      success: true,
      data: tour,
    });
  } catch (error) {
    next(error);
  }
};

export const updateTour = async (req, res, next) => {
  try {
    const tour = await Tour.findById(req.params.id);
    if (!tour) return next(errorHandler(404, "Tour not found"));

    if (tour.created_by.toString() !== req.user.id && !req.user.admin) {
      return next(errorHandler(403, "You can only update your own tours"));
    }

    const updateData = req.body;

    if (req.files && req.files["thumbnail"]) {
      const thumbnailResult = await uploadToSupabase(
        req.files["thumbnail"][0],
        "tours"
      );
      updateData.thumbnail_url = thumbnailResult.publicUrl;
    }

    if (req.files && req.files["gallery"]) {
      const galleryPromises = req.files["gallery"].map((file) =>
        uploadToSupabase(file, "tours")
      );
      const galleryResults = await Promise.all(galleryPromises);
      updateData.gallery_urls = galleryResults.map(
        (result) => result.publicUrl
      );
    }

    if (updateData.price) {
      updateData.price = Number(updateData.price);
    }

    if (updateData.duration_days) {
      updateData.duration_days = Number(updateData.duration_days);
    }

    if (updateData.is_featured !== undefined) {
      updateData.is_featured =
        updateData.is_featured === "true" || updateData.is_featured === true;
    }

    const updatedTour = await Tour.findByIdAndUpdate(
      req.params.id,
      { $set: updateData },
      { new: true }
    );

    res.status(200).json({
      success: true,
      data: updatedTour,
    });
  } catch (error) {
    next(error);
  }
};

export const deleteTour = async (req, res, next) => {
  try {
    const tour = await Tour.findById(req.params.id);
    if (!tour) return next(errorHandler(404, "Tour not found"));

    if (!req.user.admin) {
      return next(errorHandler(403, "Only admin can delete tours"));
    }

    await Tour.findByIdAndDelete(req.params.id);
    res.json({ message: "Tour deleted successfully" });
  } catch (error) {
    next(error);
  }
};

export const searchTours = async (req, res, next) => {
  try {
    const { term } = req.params;

    if (!term) {
      return next(errorHandler(400, "Search term is required"));
    }

    const numericTerm = parseFloat(term);
    const isNumeric = !isNaN(numericTerm);
    const safeTerm = escapeRegex(term);

    const searchQuery = {
      $or: [
        { title: { $regex: safeTerm, $options: "i" } },
        { description: { $regex: safeTerm, $options: "i" } },
        { location: { $regex: safeTerm, $options: "i" } },
      ],
    };

    if (isNumeric) {
      searchQuery.$or.push(
        { price: numericTerm },
        { duration_days: numericTerm }
      );
    }

    const tours = await Tour.find(searchQuery)
      .populate("created_by", "full_name")
      .sort({ created_at: -1 });

    res.status(200).json({
      success: true,
      data: tours,
    });
  } catch (error) {
    next(error);
  }
};

export const getFeaturedTours = async (req, res, next) => {
  try {
    const tours = await Tour.find({ is_featured: true })
      .populate("created_by", "full_name")
      .sort({ created_at: -1 })
      .limit(6);

    res.status(200).json({
      success: true,
      data: tours,
    });
  } catch (error) {
    next(error);
  }
};

export const getToursByLocation = async (req, res, next) => {
  try {
    const { location } = req.params;

    if (!location) {
      return next(errorHandler(400, "Location is required"));
    }

    const tours = await Tour.find({
      location: { $regex: `^${escapeRegex(location)}$`, $options: "i" },
    })
      .populate("created_by", "full_name")
      .sort({ created_at: -1 });

    res.status(200).json({
      success: true,
      data: tours,
    });
  } catch (error) {
    next(error);
  }
};

import { supabaseStorage, uploadToSupabase } from '../utils/supabaseStorage.js';
import { errorHandler } from '../utils/error.js';

export const uploadProfilePicture = async (req, res, next) => {
  try {
    if (!req.file) {
      return next(errorHandler(400, 'No file uploaded'));
    }

    
    const uploadResult = await uploadToSupabase(req.file, 'profile-pictures');
    
    res.status(200).json({
      success: true,
      message: 'File uploaded successfully',
      url: uploadResult.publicUrl,
      path: uploadResult.path
    });
  } catch (error) {
    console.error('Upload error:', error);
    next(errorHandler(500, 'Error uploading file'));
  }
};

import express from "express";
import dotenv from "dotenv";
import connectDB from "./config/db.js";
import userRoutes from "./routes/user.route.js";
import authRoutes from "./routes/auth.route.js";
import tourRoutes from "./routes/tour.route.js";
import bookingRoutes from "./routes/booking.route.js";
import blogRoutes from "./routes/blog.route.js";
import blogCommentRoutes from "./routes/blogComment.route.js";
import adminRoutes from "./routes/admin.route.js";
import adminAuthRoutes from "./routes/adminAuth.route.js";
import reviewRoutes from "./routes/review.route.js";
import notificationRoutes from "./routes/notification.route.js";
import uploadRoutes from "./routes/upload.route.js";
import cookieParser from "cookie-parser";
import { fileURLToPath } from "url";
import { dirname, join } from "path";
import cors from "cors";
import path from "path";
import fs from "fs";

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);
dotenv.config(); 

const app = express();

const clientDistPath = path.join(__dirname, "..", "client", "dist");

// Check if dist folder exists
if (!fs.existsSync(clientDistPath)) {
  console.warn(`Warning: Client dist path does not exist: ${clientDistPath}`);
} else {
  console.log(`Client dist path found: ${clientDistPath}`);
}

app.use(express.static(clientDistPath));

// Fixed CORS configuration
app.use(
  cors({
    origin: process.env.NODE_ENV === 'production' 
      ? ["https://ghuroo.onrender.com"] 
      : "http://localhost:5173",
    credentials: true,
  })
);

app.use(express.json({ limit: "50mb" }));
app.use(cookieParser());

app.use("/api/uploads", express.static(path.join(__dirname, "uploads")));

// API Routes
app.use("/api/user", userRoutes);
app.use("/api/auth", authRoutes);
app.use("/api/tours", tourRoutes);
app.use("/api/bookings", bookingRoutes);
app.use("/api/reviews", reviewRoutes);
app.use("/api/blogs", blogRoutes);
app.use("/api/blog-comments", blogCommentRoutes);
app.use("/api/admin", adminRoutes);
app.use("/api/admin/auth", adminAuthRoutes);
app.use("/api/notifications", notificationRoutes);
app.use("/api/upload", uploadRoutes);

// Catch-all handler with error handling
app.get("*", (req, res) => {
  try {
    res.sendFile(path.join(clientDistPath, "index.html"));
  } catch (error) {
    console.error("Error serving index.html:", error);
    res.status(500).send("Server Error");
  }
});

// Error handling middleware
app.use((err, req, res, next) => {
  const statusCode = err.statusCode || 500;
  const message = err.message || "Internal Server Error";
  console.error(`Error: ${message} (Status: ${statusCode})`);
  res.status(statusCode).json({
    success: false,
    message,
  });
});

const PORT = process.env.PORT || 8080;
app.listen(PORT, () => {
  console.log(`Server listening on port ${PORT}`);
});

connectDB();
